using System;using SketchToModels;
public class Lines {public int Count;public object AddBy2Points(double a,double b,double c,double d){if(Math.Abs(a)>1e-8||Math.Abs(c)>1e-8||Math.Abs(b+.05)>1e-8||Math.Abs(d-.05)>1e-8)throw new Exception("Wrong axis endpoints");Count++;return new object();}}
public class Relations {public int Count;public void AddFix(object line){Count++;}}
public class Axis {public bool Wrong;public void StartPoint(ref Array a){a=new double[]{Wrong?1:0,0,0};}public void Direction(ref Array a){a=new double[]{0,0,1};}}
public class Profile {public Lines Lines2d=new Lines();public Relations Relations2d=new Relations();public Axis Axis=new Axis();public int Calls;public object SetAxisOfRevolution(object line){Calls++;return Axis;}public void Convert3DCoordinate(double x,double y,double z,ref double u,ref double v){u=y;v=z;}public void Convert2DCoordinate(double u,double v,ref double x,ref double y,ref double z){x=0;y=u;z=v;}}
class Tests {static void Main(){var p=new Profile();var setup=new ProfileAxisSetup();setup.Ensure(p);setup.Ensure(p);if(p.Lines2d.Count!=1||p.Relations2d.Count!=1||p.Calls!=1)throw new Exception("Duplicate axis on retry");bool rejected=false;try{setup.Ensure(new Profile());}catch(InvalidOperationException){rejected=true;}if(!rejected)throw new Exception("Profile change accepted");p=new Profile();p.Axis.Wrong=true;rejected=false;try{new ProfileAxisSetup().Ensure(p);}catch(InvalidOperationException){rejected=true;}if(!rejected)throw new Exception("Wrong axis accepted");Console.WriteLine("PASS: global-Z endpoints, axis assignment, retry reuse, profile-change guard, and wrong-axis rejection (simulated profiles).");}}
